fun sortCharactersInAString(input: String): String {
      val chars = input.toCharArray()
      return chars.sorted().joinToString("")
    }

fun sortCharactersInAString(input: String): String {
      val chars = input.toCharArray()
      val ordered = chars.sorted()
      return ordered.joinToString("")
    }

