public static String sortCharactersInAString(String input) {
    List<Character> chars = input.chars().mapToObj(ch -> (char) ch).sorted().collect(Collectors.toList()); StringBuilder builder = new StringBuilder(); for (char ch : chars) builder.append(ch); return builder.toString();
 }
